import {stormRelayMenu} from './storm-relay.js?v=0.90.14';
export {stormRelayMenu} from './storm-relay.js?v=0.90.14';
import {STORM_NOTES,STORM_TRAINERS,DARIUS_STORM_ID} from './thunderplain-data.js?v=0.90.40';
import {stormState,acceptStormDarius,readStormNote,releaseStormDragon,stormDragonEncounter} from './thunderplain-rules.js?v=0.90.14';
export function handleStormSide(id,a){
 const {state:s,room,line,showDialogue,warp,rewardTransaction:commit,buildMarkers,openModal,escapeHTML:e,challengeTrainer,startWild,shop,$}=a,q=stormState(s);
 const say=(n,text,portrait)=>{const pages=[];for(const sentence of text.match(/[^.!?]+[.!?]*/g)||[text]){const last=pages.length-1;if(last>=0&&pages[last].length+sentence.length<290)pages[last]+=' '+sentence.trim();else pages.push(sentence.trim());}showDialogue(pages.map(t=>line(n,t,portrait)));},gate=a.AREA_GATES[room]?.find(g=>g.id===id);
 if(id==='bt-cart-driver'||gate?.action==='storm-cart'){
  if((s.defeatedTrainers||[]).includes(DARIUS_STORM_ID)){if(gate)void warp(gate.to,...gate.arrival);else say('Cart driver','The lightning has let up. We have fitted the spare wheel and cleared the road. Botrune is east, across the causeway. Pate and Trade still have not returned.','SHOP-DOR');}
  else say('Cart driver','Come back in a while. The wheel has split clean through. Pate and Trade raced on to Botrune for supplies before the storm closed in. Nobody can get through now. I heard an awful ruckus up the mountain to the north—shouting, then something louder than thunder. The old stone steps go that way. I cannot leave the horse.','SHOP-DOR');return true;
 }
 const accounts={
 'bt-wounded-firstlight':['First Light patrol survivor','Do not go up there alone. We lowered our weapons. He struck anyway. Dawnbloom dragged two of us out. We are carrying the dead down together. That is how bad it has become.','TRN-C02-001'],
 'bt-wounded-dawnbloom':['Dawnbloom patrol survivor','We went with a First Light truce flag. Tianzhar split the ridge between us. It is the sovereign of these storms; our grandparents prayed beneath its paintings. Darius is trying to make that power obey a frightened man.','TRN-C01-002'],
 'bt-deserter-two':['Former Common Cause scout','He has gone mad. At the gorge he said every drowned family would buy peace. Now he calls us traitors for refusing another sacrifice. Tianzhar is no weapon you can put back in a box. People here have revered it for centuries.','TRN-SC-stormBluffs-0'],
 'bt-deserter-three':['A disillusioned follower','I still believe people deserve peace. I do not believe him anymore. He speaks to the tower as though the dead can answer him. Please stop him before he makes us prove our loyalty with more lives.','SHOP-PHI'],
 'bt-storm-paintings':['Paintings in the shelter cave','Ochre coils surround tiny travellers. Blue lightning forks from a crowned dragon into mountains, leaving the people beneath untouched. The later painting shows chains around its neck and an entire watchtower breaking. Below it: “The storm shelters. The keeper does not command.”']};
 if(accounts[id]){say(...accounts[id]);return true;}
 if(gate?.action==='storm-side'){void warp(gate.to,...gate.arrival);return true;}
 if(gate?.action==='storm-darius-accepted'){if(!q.darius.accepted)say('A torn banner','Speak to the deserter beside the tent in Broken Banner Camp before following the copper cables east.');else if(!(s.defeatedTrainers||[]).includes('TRN-BT-ASCENT'))say('Mountain sentry','Challenge the ridge sentry on the upper east switchback in Broken Banner Camp before climbing into the painted caves.');else void warp(gate.to,...gate.arrival);return true;}
 if(gate?.action==='storm-darius-watch'){if(!['TRN-BT-CAVE','TRN-BT-HOLDOUT'].every(t=>(s.defeatedTrainers||[]).includes(t)))say('Last banner watch','Challenge both the cave guardian and last-banner holdout along the ascending path in Last Banner Ridge. The supply ledger nearby explains Darius’s new tactics.');else void warp(gate.to,...gate.arrival);return true;}
 if(id==='bt-relay-engineer'){say('Relay keeper Samira','The discharge trench keeps the relay safe. At the panel north of me, watch the example first: remember the lit receiver, wait while it says WAIT, then tap that same receiver only when it says TAP NOW. Route five charges for supplies. You can work another shift afterwards; the supply crews bring different rewards.','REV-MARYAM');return true;}
 if(id==='bt-relay-control'){stormRelayMenu(a);return true;}
 if(id==='bt-storm-deserter'){showDialogue([line('The deserter',STORM_NOTES.deserter[1],'REV-FARID'),line('The deserter',q.darius.accepted?'Follow the cables east. He has turned a storm shrine into another weapon.':'I will mark the ridge for you. He has a new team, and something worse chained above the camp. The cart blocks the low road. If you want anyone to reach Botrune alive, the tower has to fall silent.','REV-FARID')],()=>{commit(()=>acceptStormDarius(s));buildMarkers();});return true;}
 const note={'bt-storm-camp-note':'deserter','bt-storm-ledger':'ridge'}[id];if(note){commit(()=>readStormNote(s,note));openModal(STORM_NOTES[note][0],'<p>'+e(STORM_NOTES[note][1])+'</p>');return true;}
 const trainer=STORM_TRAINERS.find(t=>t.id===id);if(trainer){if(id===DARIUS_STORM_ID&&!(s.defeatedTrainers||[]).includes('TRN-BT-HOLDOUT'))say('Storm Crown','The last-banner holdout on the western ridge still bars the shrine. Return to Last Banner Ridge and challenge him.');else if((s.defeatedTrainers||[]).includes(id))say(trainer.name,id===DARIUS_STORM_ID?'I told them the cost would be terrible. I did not think that would mean facing it alone.':'The east path is open. I have no more orders.',trainer.portraitId);else challengeTrainer(trainer);return true;}
 if(id==='bt-storm-tether'){
  if(!(s.defeatedTrainers||[]).includes(DARIUS_STORM_ID)){say('The storm tether',STORM_NOTES.tether[1]+' Defeat Darius at Storm Crown before touching the clamps.');return true;}
  if(!q.darius.released){showDialogue([line('Storm Crown','Darius reaches for the last copper clamp. Tianzhar pulls away from him. For the first time, the thunder sounds like an answer rather than an order.'),line('Aimon','No more people below your flood. No more partners chained to your cause.','CHR-AIMON'),{...line('Copper tether','The last clamp is within reach. Beyond it, the sovereign watches every movement.'),choices:[{text:'Free Tianzhar.',action:()=>{commit(()=>releaseStormDragon(s));buildMarkers();}},{text:'Prepare first.',action:()=>{}}]}]);return true;}
  const encounter=stormDragonEncounter(s);if(!encounter){say('The open shrine',q.darius.outcome==='defeated'?'Tianzhar is dead. The shrine will remain empty.':q.darius.outcome==='captured'?'Tianzhar has joined your expedition. Its unique encounter is recorded.':'Tianzhar is already recorded among your living or lost partners. The broken tether cannot create another life.');return true;}
  showDialogue([{...line('Tianzhar','The storm sovereign watches you without Darius’s commands. Its coils rise from the shattered tower. It lowers its head, and the air between you begins to crackle.'),choices:[{text:'Approach Tianzhar.',action:()=>startWild(encounter)},{text:'Leave it in peace for now.',action:()=>{}}]}]);return true;
 }
 if(id==='bt-inn-service'){showDialogue([{...line('The Last Bell','A warm meal and a bed for the living: 400 doubloons. Your living party recovers HP, PP and status. The dead cannot return through rest.'),choices:[{text:'Rest · 400 doubloons',action:()=>{if(s.money<400){say('The innkeeper','You need 400 doubloons. Walter’s infirmary across the street offers free care.');return;}if(commit(()=>{s.money-=400;for(const u of s.party)if(u.hp>0&&!u.dead){u.hp=u.maxHp;u.status=null;u.statusTurns=0;for(const m of u.moves)m.left=m.pp;}}))say('The Last Bell','The shutters close against the rain. At dawn, the lower streets are still here, and the living are ready to travel.');}},{text:'Leave',action:()=>{}}]}]);return true;}
 if(id==='bt-records-service'){say('Civilian records keeper',s.fates?.['LDR-06']?'The sentencing orders are secured as evidence. Copies of household and food records can be read here. The abbey’s buried manuscripts remain under civilian protection; the soldiers do not control their custody.':'We keep household registers and ration lists here. The Canon sealed the abbey’s deeper archive. We have not surrendered the civil records to her guards.','SHOP-PHI');return true;}
 if(id==='bt-street-resident'){say('A Botrune resident','People still need bread, medicine and somewhere warm to sleep. The provisioner is northwest, the infirmary southwest, the Last Bell southeast and the records office northeast. The abbey square lies up the central north street.','SHOP-DOR');return true;}
 if(id==='bt-street-guard'){say(s.botrune?.phase&&s.botrune.phase!=='trial'?'A shaken soldier':'A garrison soldier',s.botrune?.phase&&s.botrune.phase!=='trial'?'They told us the prisoners had been tried. Then I saw the names were blank. I heard the boys pleading. I still hear them.':'Keep the street clear. The Canon is addressing the square. Go north if you want to hear her; the cordon will tell you where to stand.','TRN-SC-stormBluffs-0');return true;}
 return false;
}
